contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: putLock (any uint), putAmount (amount of wei to send with Put)
    // The test contract must hold at least putAmount to send it.
    function run(uint putLock, uint putAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);

        // Read stored holder before values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCbal = address(c).balance;

        // Try Put and record revert flag
        bool putReverted;
        c.Put{value: putAmount}(putLock); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            putReverted = true;
        } else {
            putReverted = false;
        }

        // Read stored holder after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General invariant to hold for all inputs: if Put did not revert then
        // 1) the stored balance did not decrease (afterBal >= beforeBal)
        // 2) the contract's Ether balance did not decrease (afterCbal >= beforeCbal)
        // 3) the increase in c's Ether balance is at least the increase in stored balance
        //    (accounts for any unexpected behavior that might create Ether out of thin air but ensures consistency)
        assert(putReverted || (afterBal >= beforeBal && afterCbal >= beforeCbal && (afterCbal - beforeCbal) >= (afterBal - beforeBal)));
    }

    // Receive to accept Ether when Collect sends to this test contract
    receive() external payable {}
}

